class Customer {
  + Name : string
}

class Broker {
  + Name : string
}

class Policy {
  + Price : float
}

class Offer {
  + Date : date
}

class Contract {
  + SigningDate : date
  + BillingCycle : string
}

class ClaimCase {
  + CaseNumber : string
}

class Estimator {
  + Name : string
}

class EstimatorReport {
  + ReportContent : string
  + DateIssued : date
}

class Compensation {
  + Amount : float
  + DatePaid : date
}

Broker "1" -- "*" Customer : follows
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" ClaimCase : files
Offer "0..1" -- "0..1" Contract : results in
Contract "1" -- "1" Policy : covers
Contract "1" -- "0..*" ClaimCase : generates
ClaimCase "1" *-- "1..*" EstimatorReport : contains
Estimator "1" -- "*" EstimatorReport : issues
ClaimCase "1" -- "0..1" Compensation : results in

@enduml

